using System;
using System.IO;

public class SummaryReport
{
    public string Title { get; set; }
    public string Content { get; set; }
    public string Date { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nDate: {Date}\nContent: {Content}";
    }
}

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output a summary report to the console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional feature: Export the report in CSV format if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(csvFilePath))
                {
                    // Write CSV header
                    writer.WriteLine("Title,Date,Content");

                    // Write CSV data
                    // Note: For simplicity, we assume Content does not contain commas or newlines.
                    // In a production environment, you should properly escape CSV fields.
                    writer.WriteLine($"{EscapeCsvField(report.Title)},{EscapeCsvField(report.Date)},{EscapeCsvField(report.Content)}");
                }

                Console.WriteLine($"Report exported to CSV: {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to export report to CSV: {ex.Message}");
            }
        }
    }

